    12	
    13	/**
    14	 * 构建查询字符串
    15	 */
    16	export function buildQueryString(params: Record<string, any>): string {
    17	  const searchParams = new URLSearchParams();
    18	  
    19	  Object.entries(params).forEach(([key, value]) => {
    20	    if (value !== undefined && value !== null && value !== '') {
    21	      if (Array.isArray(value)) {
    22	        value.forEach(item => searchParams.append(key, String(item)));
    23	      } else {
    24	        searchParams.append(key, String(value));
    25	      }
    26	    }
    27	  });
    28	  
    29	  const queryString = searchParams.toString();
    30	  return queryString ? `?${queryString}` : '';
    31	}
